import{createHash}from"node:crypto";function announcementDigest(e,t){return createHash(`sha256`).update(JSON.stringify([e,t])).digest(`base64url`).slice(0,22)}function keptAnnouncements(e,t){let n=new Set(t.flatMap(e=>e.role===`user`?[announcementDigest(e.kind,e.content)]:[])),r=Object.entries(e.messages??{}).filter(([,e])=>n.has(e));return r.length===0?{}:{announcements:Object.fromEntries(r.flatMap(([t])=>{let n=e.announcements?.[t];return n===void 0?[]:[[t,n]]})),messages:Object.fromEntries(r)}}export{announcementDigest,keptAnnouncements};